DECLARE previous uuid; was_present boolean;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'dislock v3 profile does not support DELETE'; END IF;
  IF NEW.key IS NULL OR NEW.value IS NULL OR NEW.expire_at IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.key IS DISTINCT FROM OLD.key THEN RAISE EXCEPTION 'dislock v3 key mutation unsupported'; END IF;
  SELECT token,present INTO previous,was_present FROM "mtw_provenance_dislock_v3_65c4e7516b_0"."_mtw_v3_state" WHERE key=NEW.key FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dislock v3 key outside declared domain'; END IF;
  IF TG_OP='UPDATE' AND (NOT was_present OR previous IS DISTINCT FROM OLD."_mtw_v3_version") THEN
    RAISE EXCEPTION 'dislock v3 predecessor state mismatch';
  END IF;
  NEW."_mtw_v3_version":=pg_catalog.gen_random_uuid();
  INSERT INTO "mtw_provenance_dislock_v3_65c4e7516b_0"."_mtw_v3_candidates"(token,key,predecessor,action,owner,expire_at)
    VALUES(NEW."_mtw_v3_version",NEW.key,previous,TG_OP,NEW.value,NEW.expire_at);
  RETURN NEW;
END

